using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class FixReverseCorrectionContacts {
 public static string Main(){if(Application.isPlaying)throw new Exception("Edit mode required");foreach(string scene in new[]{"DansBackyardReverse","DansBackyardForward"}){EditorSceneManager.OpenScene("Assets/Scenes/"+scene+".unity");var root=GameObject.Find("Reverse optional forest shortcuts").transform;var floor=root.GetComponentsInChildren<MeshCollider>().First(c=>c.name=="Culvert seamless floor");floor.name="Ground_Culvert seamless floor";foreach(var water in root.GetComponentsInChildren<MeshCollider>().Where(c=>c.name=="Shallow storm water").ToArray())Object.DestroyImmediate(water);EditorSceneManager.MarkSceneDirty(root.gameObject.scene);EditorSceneManager.SaveScene(root.gameObject.scene);}AssetDatabase.SaveAssets();File.WriteAllText("Docs/ReverseCorrection/contact-correction.txt","Culvert floor registered by Ground_ identity with existing VehicleSurfaceContacts; removed duplicate water-skin colliders. Water remains shallow visual/immersion feedback over continuous concrete. Global physics unchanged.");EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");AssetDatabase.Refresh();return "Local surface contact correction applied";}
}
